import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.DDk04jjR.js";const c=JSON.parse('{"title":"Основи 3D-друку","description":"Технології 3D-друку, підготовка моделей та перший друк","frontmatter":{"layout":"page","title":"Основи 3D-друку","description":"Технології 3D-друку, підготовка моделей та перший друк"},"headers":[],"relativePath":"3d-print-basics.md","filePath":"3d-print-basics.md"}'),i={name:"3d-print-basics.md"};function e(d,t,n,h,s,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="🖨️-основи-3d-друку" tabindex="-1">🖨️ Основи 3D-друку <a class="header-anchor" href="#🖨️-основи-3d-друку" aria-label="Permalink to &quot;🖨️ Основи 3D-друку&quot;">​</a></h1><h2 id="що-таке-3d-друк" tabindex="-1">Що таке 3D-друк? <a class="header-anchor" href="#що-таке-3d-друк" aria-label="Permalink to &quot;Що таке 3D-друк?&quot;">​</a></h2><p><strong>3D-друк</strong> (адитивне виробництво) — це створення фізичних об&#39;єктів шар за шаром на основі цифрової 3D-моделі. Це технологія, яка дозволяє перетворити віртуальну ідею на реальний предмет.</p><blockquote><p>💡 3D-друк використовується в освіті, медицині, інженерії, архітектурі, дизайні та навіть у космічній індустрії.</p></blockquote><hr><h2 id="основні-технологіі" tabindex="-1">Основні технології <a class="header-anchor" href="#основні-технологіі" aria-label="Permalink to &quot;Основні технології&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Технологія</th><th>Опис</th><th>Матеріал</th></tr></thead><tbody><tr><td><strong>FDM</strong> (Fused Deposition Modeling)</td><td>Друк розплавленим пластиком через сопло</td><td>PLA, ABS, PETG</td></tr><tr><td><strong>SLA</strong> (Stereolithography)</td><td>Затвердіння рідкої смоли ультрафіолетом</td><td>Фотополімерна смола</td></tr><tr><td><strong>SLS</strong> (Selective Laser Sintering)</td><td>Спікання порошку лазером</td><td>Нейлон, поліамід</td></tr></tbody></table><blockquote><p>🏫 У нашій лабораторії ми працюємо переважно з <strong>FDM-технологією</strong> — найпоширенішою та найдоступнішою.</p></blockquote><hr><h2 id="від-моделі-до-друку-етапи" tabindex="-1">Від моделі до друку: етапи <a class="header-anchor" href="#від-моделі-до-друку-етапи" aria-label="Permalink to &quot;Від моделі до друку: етапи&quot;">​</a></h2><h3 id="_1-3d-моделювання" tabindex="-1">1. 3D-моделювання <a class="header-anchor" href="#_1-3d-моделювання" aria-label="Permalink to &quot;1. 3D-моделювання&quot;">​</a></h3><p>Створіть модель у <strong>Blender</strong>, <strong>Fusion 360</strong> або іншій програмі та експортуйте у форматі <strong>STL</strong> або <strong>OBJ</strong>.</p><h3 id="_2-слаисинг" tabindex="-1">2. Слайсинг <a class="header-anchor" href="#_2-слаисинг" aria-label="Permalink to &quot;2. Слайсинг&quot;">​</a></h3><p>Імпортуйте модель у <strong>слайсер</strong> — програму, яка розрізає модель на шари та генерує інструкції для принтера (<strong>G-code</strong>).</p><p><strong>Популярні слайсери:</strong></p><ul><li><strong>Cura</strong> (безкоштовний, від Ultimaker)</li><li><strong>PrusaSlicer</strong> (безкоштовний, від Prusa)</li><li><strong>Simplify3D</strong> (платний)</li></ul><h3 id="_3-налаштування-параметрів-друку" tabindex="-1">3. Налаштування параметрів друку <a class="header-anchor" href="#_3-налаштування-параметрів-друку" aria-label="Permalink to &quot;3. Налаштування параметрів друку&quot;">​</a></h3><h3 id="_4-друк" tabindex="-1">4. Друк <a class="header-anchor" href="#_4-друк" aria-label="Permalink to &quot;4. Друк&quot;">​</a></h3><h3 id="_5-постобробка" tabindex="-1">5. Постобробка <a class="header-anchor" href="#_5-постобробка" aria-label="Permalink to &quot;5. Постобробка&quot;">​</a></h3><hr><h2 id="основні-параметри-друку" tabindex="-1">Основні параметри друку <a class="header-anchor" href="#основні-параметри-друку" aria-label="Permalink to &quot;Основні параметри друку&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Опис</th><th>Типове значення</th></tr></thead><tbody><tr><td><strong>Висота шару</strong></td><td>Товщина одного шару</td><td>0.2 мм (стандарт)</td></tr><tr><td><strong>Заповнення (Infill)</strong></td><td>% заповнення внутрішнього об&#39;єму</td><td>15–20%</td></tr><tr><td><strong>Швидкість друку</strong></td><td>Швидкість руху сопла</td><td>50–60 мм/с</td></tr><tr><td><strong>Температура сопла</strong></td><td>Залежить від матеріалу</td><td>190–220°C (PLA)</td></tr><tr><td><strong>Температура столу</strong></td><td>Підігрів поверхні</td><td>60°C (PLA)</td></tr><tr><td><strong>Підтримки (Supports)</strong></td><td>Допоміжні структури для навислих частин</td><td>За потребою</td></tr></tbody></table><hr><h2 id="матеріали-для-fdm-друку" tabindex="-1">Матеріали для FDM-друку <a class="header-anchor" href="#матеріали-для-fdm-друку" aria-label="Permalink to &quot;Матеріали для FDM-друку&quot;">​</a></h2><h3 id="pla-полілактид" tabindex="-1">PLA (полілактид) <a class="header-anchor" href="#pla-полілактид" aria-label="Permalink to &quot;PLA (полілактид)&quot;">​</a></h3><ul><li>✅ Найпопулярніший матеріал для початківців</li><li>✅ Легкий у друці, мінімальна деформація</li><li>✅ Біорозкладний (на основі кукурудзяного крохмалю)</li><li>❌ Невисока термостійкість (~60°C)</li></ul><h3 id="abs-акрилонітрилбутадієнстирол" tabindex="-1">ABS (акрилонітрилбутадієнстирол) <a class="header-anchor" href="#abs-акрилонітрилбутадієнстирол" aria-label="Permalink to &quot;ABS (акрилонітрилбутадієнстирол)&quot;">​</a></h3><ul><li>✅ Міцний та термостійкий (~100°C)</li><li>✅ Можна обробляти ацетоном для гладкої поверхні</li><li>❌ Потребує закритої камери та підігріву столу</li><li>❌ Виділяє запах при друці</li></ul><h3 id="petg-поліетилентерефталатгліколь" tabindex="-1">PETG (поліетилентерефталатгліколь) <a class="header-anchor" href="#petg-поліетилентерефталатгліколь" aria-label="Permalink to &quot;PETG (поліетилентерефталатгліколь)&quot;">​</a></h3><ul><li>✅ Баланс між PLA та ABS</li><li>✅ Гнучкий, стійкий до ударів</li><li>✅ Водонепроникний</li><li>❌ Може тягнути «нитки» при друці</li></ul><hr><h2 id="підготовка-моделі-до-друку" tabindex="-1">Підготовка моделі до друку <a class="header-anchor" href="#підготовка-моделі-до-друку" aria-label="Permalink to &quot;Підготовка моделі до друку&quot;">​</a></h2><h3 id="правила-проєктування-для-3d-друку" tabindex="-1">Правила проєктування для 3D-друку <a class="header-anchor" href="#правила-проєктування-для-3d-друку" aria-label="Permalink to &quot;Правила проєктування для 3D-друку&quot;">​</a></h3><ol><li><strong>Мінімальна товщина стінки</strong> — не менше 1.2 мм (для FDM)</li><li><strong>Уникайте великих навісів</strong> — кут більше 45° потребує підтримок</li><li><strong>Зазори для з&#39;єднань</strong> — додавайте 0.2–0.3 мм для посадки деталей</li><li><strong>Орієнтація моделі</strong> — розмістіть найбільшу площину вниз</li><li><strong>Уникайте гострих кутів</strong> — додавайте скруглення (fillet) для міцності</li></ol><hr><h2 id="першии-друк-покроково" tabindex="-1">Перший друк: покроково <a class="header-anchor" href="#першии-друк-покроково" aria-label="Permalink to &quot;Перший друк: покроково&quot;">​</a></h2><h3 id="крок-1-—-підготуите-модель" tabindex="-1">Крок 1 — Підготуйте модель <a class="header-anchor" href="#крок-1-—-підготуите-модель" aria-label="Permalink to &quot;Крок 1 — Підготуйте модель&quot;">​</a></h3><ul><li>Переконайтесь, що модель «водонепроникна» (без розривів у сітці)</li><li>Експортуйте у <strong>STL</strong> з правильними одиницями (мм)</li></ul><h3 id="крок-2-—-відкриите-модель-у-слаисері" tabindex="-1">Крок 2 — Відкрийте модель у слайсері <a class="header-anchor" href="#крок-2-—-відкриите-модель-у-слаисері" aria-label="Permalink to &quot;Крок 2 — Відкрийте модель у слайсері&quot;">​</a></h3><ol><li>Завантажте та встановіть <strong>Cura</strong> або <strong>PrusaSlicer</strong></li><li>Оберіть свій принтер зі списку</li><li>Імпортуйте STL-файл</li></ol><h3 id="крок-3-—-налаштуите-параметри" tabindex="-1">Крок 3 — Налаштуйте параметри <a class="header-anchor" href="#крок-3-—-налаштуите-параметри" aria-label="Permalink to &quot;Крок 3 — Налаштуйте параметри&quot;">​</a></h3><ul><li>Висота шару: <strong>0.2 мм</strong></li><li>Заповнення: <strong>20%</strong></li><li>Підтримки: <strong>увімкніть</strong>, якщо є навіси</li><li>Адгезія: <strong>Brim</strong> (додатковий контур для кращого прилипання)</li></ul><h3 id="крок-4-—-слаисинг-та-збереження" tabindex="-1">Крок 4 — Слайсинг та збереження <a class="header-anchor" href="#крок-4-—-слаисинг-та-збереження" aria-label="Permalink to &quot;Крок 4 — Слайсинг та збереження&quot;">​</a></h3><ol><li>Натисніть <strong>Slice</strong> (Нарізати)</li><li>Перегляньте попередній вигляд шарів</li><li>Збережіть <strong>G-code</strong> на SD-карту або USB</li></ol><h3 id="крок-5-—-друк" tabindex="-1">Крок 5 — Друк <a class="header-anchor" href="#крок-5-—-друк" aria-label="Permalink to &quot;Крок 5 — Друк&quot;">​</a></h3><ol><li>Увімкніть принтер та нагрійте стіл і сопло</li><li>Переконайтесь, що стіл чистий та рівний</li><li>Запустіть друк і спостерігайте за першими шарами</li></ol><hr><h2 id="типові-проблеми-та-іх-вирішення" tabindex="-1">Типові проблеми та їх вирішення <a class="header-anchor" href="#типові-проблеми-та-іх-вирішення" aria-label="Permalink to &quot;Типові проблеми та їх вирішення&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Проблема</th><th>Можлива причина</th><th>Рішення</th></tr></thead><tbody><tr><td>Модель не прилипає до столу</td><td>Забруднений стіл, низька температура</td><td>Очистіть стіл, збільшіть температуру, додайте Brim</td></tr><tr><td>Нитки між частинами</td><td>Висока температура, відсутній ретракт</td><td>Зменшіть температуру, увімкніть/збільшіть ретракт</td></tr><tr><td>Шари відшаровуються</td><td>Недостатня адгезія між шарами</td><td>Збільшіть температуру сопла, зменшіть швидкість</td></tr><tr><td>Деформація (warping)</td><td>Різниця температур</td><td>Увімкніть підігрів столу, використовуйте закриту камеру</td></tr></tbody></table><hr><h2 id="що-далі" tabindex="-1">Що далі? <a class="header-anchor" href="#що-далі" aria-label="Permalink to &quot;Що далі?&quot;">​</a></h2><ul><li>Спробуйте друк з різними матеріалами</li><li>Вивчіть складніші налаштування слайсера (модифікатор заповнення, змінна висота шару)</li><li>Опануйте <strong>постобробку</strong>: шліфування, фарбування, склеювання</li><li>Створіть власний проєкт від ідеї до готового виробу!</li></ul>',52)])])}const b=a(i,[["render",e]]);export{c as __pageData,b as default};
